module traffic_light_probability(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] T_g,\n    input [7:0] T_y,\n    input [7:0] T_r,\n    input [3:0] num_obs,\n    input [23:0] obs_0,\n    input [23:0] obs_1,\n    input [23:0] obs_2,\n    input [23:0] obs_3,\n    input [23:0] obs_4,\n    input [23:0] obs_5,\n    input [23:0] obs_6,\n    input [23:0] obs_7,\n    input [15:0] query_time,\n    input [1:0] query_color,\n    output reg [15:0] probability,\n    output reg done\n);\n\n    // State declarations\n    localparam [3:0] IDLE          = 4'd0;\n    localparam [3:0] COMPUTE_CYCLE = 4'd1;\n    localparam [3:0] PROCESS_OBS   = 4'd2;\n    localparam [3:0] INTERSECT     = 4'd3;\n    localparam [3:0] QUERY         = 4'd4;\n    localparam [3:0] RESULT        = 4'd5;\n    \n    reg [3:0] state;\n    reg [3:0] obs_counter;\n    reg [15:0] total_cycle;\n    reg [15:0] obs_time;\n    reg [1:0] obs_color;\n    reg [15:0] valid_length;\n    reg [7:0] cycle_counter;\n\n    // Initialize in reset\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            probability <= 16'd0;\n            obs_counter <= 4'd0;\n            total_cycle <= 16'd0;\n            cycle_counter <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= COMPUTE_CYCLE;\n                        obs_counter <= 4'd0;\n                        cycle_counter <= 8'd0;\n                    end\n                end\n                \n                COMPUTE_CYCLE: begin\n                    total_cycle <= {8'd0, T_g} + {8'd0, T_y} + {8'd0, T_r};\n                    state <= (num_obs > 4'd0) ? PROCESS_OBS : QUERY;\n                end\n                \n                PROCESS_OBS: begin\n                    // Select current observation\n                    case (obs_counter)\n                        4'd0: {obs_time, obs_color} <= {obs_0[15:0], obs_0[17:16]};\n                        4'd1: {obs_time, obs_color} <= {obs_1[15:0], obs_1[17:16]};\n                        4'd2: {obs_time, obs_color} <= {obs_2[15:0], obs_2[17:16]};\n                        4'd3: {obs_time, obs_color} <= {obs_3[15:0], obs_3[17:16]};\n                        4'd4: {obs_time, obs_color} <= {obs_4[15:0], obs_4[17:16]};\n                        4'd5: {obs_time, obs_color} <= {obs_5[15:0], obs_5[17:16]};\n                        4'd6: {obs_time, obs_color} <= {obs_6[15:0], obs_6[17:16]};\n                        4'd7: {obs_time, obs_color} <= {obs_7[15:0], obs_7[17:16]};\n                    endcase\n                    state <= INTERSECT;\n                end\n                \n                INTERSECT: begin\n                    // Simplified intersection (placeholder for actual logic)\n                    cycle_counter <= cycle_counter + 8'd1;\n                    if (obs_counter < num_obs) begin\n                        obs_counter <= obs_counter + 4'd1;\n                        state <= PROCESS_OBS;\n                    end else begin\n                        state <= QUERY;\n                    end\n                end\n                \n                QUERY: begin\n                    valid_length <= (query_color == 2'd0) ? {8'd0, T_g} :\n                                   (query_color == 2'd1) ? {8'd0, T_y} :\n                                   {8'd0, T_r};  // Default to red\n                    probability <= (valid_length << 8) / total_cycle;\n                    state <= RESULT;\n                end\n                \n                RESULT: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule